package dev.veltraph.client.navigation;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class GroundJumpApproachTest {
    private static final Vec3 ACTUAL=new Vec3(.6011004412049329,70,7.245771955829208),VELOCITY=new Vec3(-.009536527754196916,-.0784000015258789,.11718832680231658),TARGET=new Vec3(.5,71,8.5);
    @Test void approachClockRejectsRollbackAndNeverRestartsItsDeadline(){assertTrue(GroundJumpApproach.currentClock(100,150,200));assertFalse(GroundJumpApproach.currentClock(100,150,149));assertFalse(GroundJumpApproach.currentClock(100,100,99));assertFalse(GroundJumpApproach.currentClock(100,1200,1301));assertTrue(GroundJumpApproach.currentClock(100,1200,1300));}
    @Test void sourceLineageIncludesActualDriftAndEveryUncertaintyEndpoint(){var source=new dev.veltraph.client.world.BlockPos(0,70,7);assertTrue(GroundJumpApproach.sameSourceCell(source,new Vec3(.5,70,7.5)));assertFalse(GroundJumpApproach.sameSourceCell(source,new Vec3(.5,70,8.01)));assertFalse(GroundJumpApproach.sameSourceCell(source,new Vec3(1.001,70,7.5)));double pad=GroundJumpApproach.coastUncertainty();assertFalse(GroundJumpApproach.sameSourceCell(source,new Vec3(.5,70,7.95+pad)));}
    @Test void nativeCoastEnvelopeIncludesValidatedPositionVelocityAndHeadingIntervals(){double multiplier=(double).6F*(double).91F;double headingTail=GroundJumpApproach.stepUncertainty()/(1-multiplier);double velocityTail=.025/(1-multiplier);assertTrue(headingTail>.025);assertTrue(GroundJumpApproach.coastUncertainty()>=.025+velocityTail+headingTail);}
    @Test void ownedJumpDropAndLandingBrakeCannotBePreemptedByApproach(){for(var phase:new GroundLocomotionPolicy.Phase[]{GroundLocomotionPolicy.Phase.TAKEOFF,GroundLocomotionPolicy.Phase.AIRBORNE,GroundLocomotionPolicy.Phase.LANDING_BRAKE,GroundLocomotionPolicy.Phase.DROPPING,GroundLocomotionPolicy.Phase.BLOCKED})assertFalse(GroundJumpApproach.newEdgePhase(phase));assertTrue(GroundJumpApproach.newEdgePhase(GroundLocomotionPolicy.Phase.READY));assertTrue(GroundJumpApproach.newEdgePhase(GroundLocomotionPolicy.Phase.LANDED));}
    @Test void maximumAdmittedHeadingStepHasBoundedImpulseInterval(){double maximum=2*((double).1F*(double).98F)*Math.sin(Math.toRadians(12)/2);assertTrue(maximum<.025);for(var key:GroundJumpApproach.Key.values()){var a=GroundJumpApproach.impulse(key,0);var b=GroundJumpApproach.impulse(key,12);assertTrue(a.horizontalDistanceTo(b)<=maximum+.000001);}}
    @Test void actualOffsetStanceRanksFiniteOrdinarySideBackActionsWithoutChangingTarget(){var plans=GroundJumpApproach.candidates(ACTUAL,VELOCITY,6.822736f,TARGET);assertFalse(plans.isEmpty());assertTrue(plans.size()<=GroundJumpApproach.Key.values().length);assertTrue(plans.stream().allMatch(p->p.next().y()==70&&p.coast().y()==70));assertEquals(plans,GroundJumpApproach.candidates(ACTUAL,VELOCITY,6.822736f,TARGET));}
    @Test void nativeApproachKeysNeverContainForwardJumpSprintOrPoseMutation(){for(var key:GroundJumpApproach.Key.values()){var impulse=GroundJumpApproach.impulse(key,0);assertTrue(impulse.z()<=0);assertEquals(0,impulse.y());assertTrue(Math.hypot(impulse.x(),impulse.z())<.099);}}
    @Test void actualNativeLeftRightAxesArePositiveNegativeLocalX(){assertTrue(GroundJumpApproach.impulse(GroundJumpApproach.Key.LEFT,0).x()>0);assertTrue(GroundJumpApproach.impulse(GroundJumpApproach.Key.RIGHT,0).x()<0);assertTrue(GroundJumpApproach.impulse(GroundJumpApproach.Key.BACK_LEFT,0).x()>0);assertTrue(GroundJumpApproach.impulse(GroundJumpApproach.Key.BACK_LEFT,0).z()<0);}
    @Test void capturedNBackLeftStepMatchesCorrectedNativeRotation(){var actual=new Vec3(.6011004412049329,70,7.245771955829208);var v=new Vec3(-.009536527754196916,-.0784000015258789,.11718832680231658);var impulse=GroundJumpApproach.impulse(GroundJumpApproach.Key.BACK_LEFT,7.7011657f);var predicted=new Vec3(actual.x()+v.x()+impulse.x(),70,actual.z()+v.z()+impulse.z());var observed=new Vec3(.6711069415,70,7.3023557876);assertEquals(.0020000077942658664,predicted.distanceTo(observed),.000001);assertTrue(predicted.distanceTo(observed)<.025);assertTrue(predicted.x()>actual.x());}

    @Test void safeJumpReadinessNeedsLateralInertiaSettledUnderSameCardinalEdge(){assertFalse(GroundJumpApproach.lateralSettled(VELOCITY,ACTUAL,TARGET));assertTrue(GroundJumpApproach.lateralSettled(new Vec3(.005,-.0784,.117),ACTUAL,TARGET));}
    @Test void foreignOrNonCardinalAndNonfiniteInputsProduceNoApproachPlan(){assertTrue(GroundJumpApproach.candidates(ACTUAL,VELOCITY,Float.NaN,TARGET).isEmpty());assertTrue(GroundJumpApproach.candidates(ACTUAL,VELOCITY,0,new Vec3(1.5,71,8.5)).isEmpty());assertTrue(GroundJumpApproach.candidates(new Vec3(Double.NaN,70,7),VELOCITY,0,TARGET).isEmpty());}
}
